import{_ as i,a0 as s,w as m,s as l,I as e,x as p,a1 as a,A as o,ao as E}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"一步一腳印：GNOME十八年進化史 | LCTT x X-CMD","titleTemplate":false,"description":"一步一腳印：GNOME十八年進化史 | LCTT (201603) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一步一腳印：GNOME十八年進化史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一步一腳印：GNOME十八年進化史 | LCTT (201603) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201603/20151020 18 Years of GNOME Design and Software Evolution--Step by Step","title":"一步一腳印：GNOME十八年進化史","tag":"201603","desc":""},"relativePath":"201603/20151020 18 Years of GNOME Design and Software Evolution--Step by Step.md","filePath":"[post].md"}'),G={name:"201603/20151020 18 Years of GNOME Design and Software Evolution--Step by Step.md"};function n(N,t,M,O,u,g){const r=s("Link");return m(),l("div",null,[t[18]||(t[18]=e("h1",{id:"一步一腳印-gnome十八年進化史",tabindex:"-1"},[p("一步一腳印：GNOME十八年進化史 "),e("a",{class:"header-anchor",href:"#一步一腳印-gnome十八年進化史","aria-label":"Permalink to “一步一腳印：GNOME十八年進化史”"},"​")],-1)),t[19]||(t[19]=e("p",null,"注：youtube 視頻",-1)),t[20]||(t[20]=e("iframe",{width:"660",height:"371",src:"https://www.youtube.com/embed/MtmcO5vRNFQ?feature=oembed",frameborder:"0",allowfullscreen:""},null,-1)),e("p",null,[a(r,{href:"https://www.gnome.org/"},{default:o(()=>[...t[0]||(t[0]=[p("GNOME",-1)])]),_:1}),t[1]||(t[1]=p(" （GNU Object Model Environment）由兩位墨西哥的程序員 Miguel de Icaza 和 Federico Mena 始創於1997年8月15日。GNOME 自由軟件計劃由志願者和全職開發者來開發一個桌面環境及其應用程序。GNOME 桌面環境的所有部分都由開源軟件組成，並且支持Linux， FreeBSD， OpenBSD 等操作系統。",-1))]),t[21]||(t[21]=E('<p>現在就讓我穿越到1997年來看看 GNOME 的第一個版本：</p><h3 id="gnome-1" tabindex="-1">GNOME 1 <a class="header-anchor" href="#gnome-1" aria-label="Permalink to “GNOME 1”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/1.0/gnome.png" alt="GNOME 1.0 - GNOME 發佈的第一個重大版本"></p><p><em>GNOME 1.0 (1997) – GNOME 發佈的第一個重大版本</em></p><p><img src="https://raw.githubusercontent.com/paulcarroty/Articles/master/GNOME_History/1.2/1361441938.or.86429.png" alt="GNOME 1.2 Bongo"></p><p><em>GNOME 1.2 “Bongo”，2000</em></p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/1.4/1.png" alt="GNOME 1.4 Tranquility"></p><p><em>GNOME 1.4 “Tranquility”， 2001</em></p><h3 id="gnome-2" tabindex="-1">GNOME 2 <a class="header-anchor" href="#gnome-2" aria-label="Permalink to “GNOME 2”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.0/1.png" alt="GNOME 2.0"></p><p><em>GNOME 2.0， 2002</em></p><p>重大更新，基於 GTK+ 2。引入了人機界面指南（Human Interface Guidelines）。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.2/GNOME_2.2_catala.png" alt="GNOME 2.2"></p><p><em>GNOME 2.2 2003</em></p><p>改進了多媒體和文件管理器。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.4/gnome-desktop.png" alt="GNOME 2.4 Temujin"></p><p><em>GNOME 2.4 “Temujin”, 2003</em></p><p>首次發佈 Epiphany 瀏覽器，增添了輔助功能（accessibility）。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.6/Adam_Hooper.png" alt="GNOME 2.6"></p><p><em>GNOME 2.6， 2004</em></p><p>Nautilus 成為主要的文件管理工具，同時引入了新的 GTK+ 對話框。作為對這個版本中變化的結果，創建了一個存在時間不久的分叉版本：GoneME。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.8/3.png" alt="GNOME 2.8"></p><p><em>GNOME 2.8， 2004</em></p><p>改良了對可移動設備的支持，並新增了 Evolution 郵件應用。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.10/GNOME-Screenshot-2.10-FC4.png" alt="GNOME 2.10"></p><p><em>GNOME 2.10， 2005</em></p><p>減小了內存需求和提升了性能。增加了新的面板小應用（調製解調器控制、磁盤掛載器和回收站組件）以及 Totem 影片播放器和 Sound Juicer CD抓取工具。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.12/gnome-livecd.jpg" alt="GNOME 2.12"></p><p><em>GNOME 2.12， 2005</em></p><p>改進了 Nautilus，改進了應用程序間的剪切/粘貼功能和 freedesktop.org 的整合。 新增 Evince PDF 閲讀器；新默認主題 Clearlooks；菜單編輯器、鑰匙環管理器和管理員工具。基於 GTK+2.8，支持 Cairo。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.14/debian4-stable.jpg" alt="GNOME 2.14"></p><p><em>GNOME 2.14， 2006</em></p><p>性能提升（某些情況下超過 100%）；增強用户界面的易用性；GStreamer 0.10 多媒體框架。增加了 Ekiga 視頻會議應用、Deskbar 搜索工具、Pessulus 權限管理器、快速切換用户功能和 Sabayon 系統管理員工具。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.16/Gnome-2.16-screenshot.png" alt="GNOME 2.16"></p><p><em>GNOME 2.16， 2006</em></p><p>性能提升。增加了 Tomboy 筆記應用、Baobab 磁盤用量分析應用、Orca 屏幕閲讀器以及 GNOME 電源管理程序（延長了筆記本電池壽命）。改進了 Totem、Nautilus。Metacity 窗口管理器的合成（compositing）支持。新的圖標主題。基於 GTK+ 2.0 的全新打印對話框。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.18/Gnome-2.18.1.png" alt="GNOME 2.18"></p><p><em>GNOME 2.18， 2007</em></p><p>性能提升。增加了 Seahorse GPG 安全應用，可以對郵件和本地文件進行加密。Baobab 改進了環狀圖表顯示方式的支持。Orca 屏幕閲讀器。改進了 Evince、Epiphany、GNOME 電源管理、音量控制。增加了兩款新遊戲：GNOME 數獨和 glChess 國際象棋。支持 MP3 和 AAC 音頻解碼。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.20/rnintroduction-screenshot.png" alt="GNOME 2.20"></p><p><em>GNOME 2.20， 2007</em></p><p>發佈十週年版本。Evolution 增加了備份功能。改進了 Epiphany、EOG、GNOME 電源管理。Seahorse 中的鑰匙環密碼管理功能。增加：在 Evince 中可以編輯PDF文檔、文件管理界面中整合了搜索模組、自動安裝多媒體解碼器。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.22/GNOME-2-22-2-Released-2.png" alt="GNOME 2.22, 2008"></p><p><em>GNOME 2.22， 2008</em></p><p>新增 Cheese 應用，它是一個可以截取網絡攝像頭和遠程桌面圖像的工具。Metacity 支持基本的窗口合成（compositing）。引入 GVFS（LCTT譯註：GNOME Virtual file system，GNOME 虛擬文件系統）。改善了Totem 播放 DVD 和 YouTube 的效果，支持播放 MythTV。時鐘小應用支持國際化。在 Evolution 中新增了谷歌日曆以及為信息添加標籤的功能。改進了 Evince、Tomboy、 Sound Juicer 和計算器。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.24/gnome-224.jpg" alt="GNOME 2.24"></p><p><em>GNOME 2.24， 2008</em></p><p>新增了 Empathy 即時通訊軟件。Ekiga 升級至3.0版本。Nautilus 支持標籤式瀏覽，更好的支持了多屏幕顯示方式和數字電視功能。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.26/gnome226-large_001.jpg" alt="GNOME 2.26"></p><p><em>GNOME 2.26， 2009</em></p><p>新增光盤刻錄應用 Brasero。簡化了文件分享的流程。改進了媒體播放器的性能。支持多顯示器和指紋識別器。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.28/1.png" alt="GNOME 2.28"></p><p><em>GNOME 2.28， 2009</em></p><p>增加了 GNOME 藍牙模組。改進了 Epiphany 網頁瀏覽器、Empathy 即時通訊軟件、時間追蹤器和輔助功能。GTK+ 升級至2.18版本。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.30/GNOME2.30.png" alt="GNOME 2.30"></p><p><em>GNOME 2.30， 2010</em></p><p>改進了 Nautilus 文件管理器、Empathy 即時通訊軟件、Tomboy、Evince、時間追蹤器、Epiphany 和 Vinagre。藉助 GVFS 通過 libimobiledevice（LCTT 譯註：支持iOS®設備跨平台使用的工具協議庫)部分地支持了 iPod 和 iPod Touch 設備。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/2.32/gnome-2-32.png.en_GB.png" alt="GNOME 2.32"></p><p><em>GNOME 2.32， 2010</em></p><p>新增 Rygel 媒體分享工具和 GNOME 色彩管理器。改進了 Empathy 即時通訊軟件、Evince、Nautilus 文件管理器等。由於計劃於2010年9月發佈3.0版本，因此大部分開發者的精力都由2.3x轉移至了3.0版本。</p><h3 id="gnome-3" tabindex="-1">GNOME 3 <a class="header-anchor" href="#gnome-3" aria-label="Permalink to “GNOME 3”">​</a></h3><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/3.0/chat-3-0.png" alt="GNOME 3.0"></p><p><em>GNOME 3.0， 2011</em></p><p>引入 GNOME Shell，這是一個重新設計的、具有更簡練更集中的選項的框架。基於 Mallard 標記語言的話題導向型幫助系統。支持窗口並列堆疊。啓用新的視覺主題和默認字體。採用 GTK+ 3.0，具有更好的語言綁定、主題、觸控以及多平台支持。去除了那些長期棄用的 API。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/3.2/gdm.png" alt="GNOME 3.2"></p><p><em>GNOME 3.2、 2011</em></p><p>支持在線帳户、“瀏覽器”應用。新增通訊錄應用和文檔文件管理器。“文件管理器”支持快速預覽。較大的整合，文檔更完善，以及對外觀的改善和各種性能提升。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/3.4/application-view.png" alt="GNOME 3.4"></p><p><em>GNOME 3.4, 2012</em></p><p>全新外觀的 GNOME 3 應用程序：“文件”、Epiphany（更名為“瀏覽器”）、“GNOME 通訊錄”。可以在活動概覽中搜索本地文件。支持應用菜單。煥然一新的界面元素：新的顏色拾取器、重新設計的滾動條、更易使用的旋鈕以及可隱藏的標題欄。支持平滑滾動。全新的動態壁紙。在系統設置中改進了對 Wacom 數位板的支持。更簡便的擴展應用管理。更好的硬件支持。面向主題的幫助文檔。在 Empathy 中提供了對視頻電話和動態信息的支持。更好的輔助功能：提升 Orca 整合度，增強高對比度模式，以及全新的縮放設置。大量的應用增強和對細節的改進。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/3.6/gnome-3-6.png" alt="GNOME 3.6"></p><p><em>GNOME 3.6, 2012</em></p><p>全新設計的核心元素：新的應用按鈕和改進的活動概覽佈局。新的登錄和鎖定界面。重新設計的通知欄。通知現在更智能，可見性更高，同時更容易關閉。改進了系統設置的界面和設定邏輯。用户菜單默認顯示關閉電源操作。整合的輸入方式。輔助功能一直開啓。新的應用：Boxes 桌面虛擬化，曾在 GNOME 3.4中發佈過預覽版。Clocks 時鐘，可以顯示世界時間。更新了磁盤用量分析、Empathy 和字體查看器的外觀。改進了 Orca 對布萊葉盲文的支持。 在“瀏覽器”中，用最常訪問頁面取代了之前的空白起始頁，增添了更好的全屏模式並使用了 WebKit2 測試版引擎。 Evolution 開始使用 WebKit 顯示郵件內容。 改進了“磁盤”功能。 改進了“文件”應用（即之前的 Nautilus），新增諸如最近訪問的文件和搜索等功能。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/3.8/applications-view.png" alt="GNOME 3.8"></p><p><em>GNOME 3.8, 2013</em></p><p>令人耳目一新的核心組件：新應用界面可以分別顯示常用應用及全部應用。窗口布局得到全面改造。新的屏幕即現式（OSD）輸入法開關。通知和信息現在會對屏幕邊緣的點擊作出回應。為那些喜歡傳統桌面的用户提供了經典模式。重新設計了設置界面的工具欄。新的初始化引導流程。“GNOME 在線帳户”添加了對更多供應商的支持。“瀏覽器”正式啓用 WebKit2 引擎，有了一個新的私密瀏覽模式。“文檔”支持雙頁模式並且整合了 “Google 文檔”。“通訊錄”的 UI 升級。“GNOME 文件”、“GNOME Boxes”和“GNOME 磁盤”都得到了大幅改進。集成了 ownCloud。兩款全新的 GNOME 核心應用：“GNOME 時鐘”和“GNOME 天氣”。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/3.10/GNOME-3-10-Release-Schedule-2.png" alt="GNOME 3.10"></p><p><em>GNOME 3.10, 2013</em></p><p>全新打造的系統狀態區，能夠更直觀的縱覽全局。一系列新應用，包括 “GNOME 地圖”、“GNOME 備忘錄”、 “GNOME 音樂”和“GNOME 照片”。新的基於位置的功能，如自動時區和世界時鐘。支持高分辨率及智能卡。 基於 GLib 2.38 提供了對 D-Bus 的支持。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/3.12/app-folders.png" alt="GNOME 3.12"></p><p><em>GNOME 3.12, 2014</em></p><p>改進了概覽中的鍵盤導航和窗口選擇，基於易用性測試對初始設置進行了修改。有線網絡圖標重新回到了狀態欄上，在“應用”視圖中可以自定義應用文件夾。在大量應用的對話框中引入了新的 GTK+ 小工具，同時使用了新的 GTK+ 標籤風格。“GNOME 視頻”，“GNOME 終端”以及 Gedit 都改用了全新外觀，更貼合 HIG（LCTT 譯註：Human Interface Guidelines，人機界面指南）。在 GNOME Shell 的終端仿真器中提供了搜索預測功能。增強了對 “GNOME 軟件”和高分辨率顯示屏的支持。提供了新的錄音工具。增加了新的桌面通知接口。在向 Wayland 移植的進度中達到了可用的程度，可用選擇性地預覽體驗。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/3.14/Top-Features-of-GNOME-3-14-Gallery-459893-2.jpg" alt="GNOME 3.14"></p><p><em>GNOME 3.14, 2014</em></p><p>更炫酷的桌面環境效果，改善了對觸摸屏的支持。“GNOME 軟件”可以管理安裝的插件。在“GNOME 照片”中可以訪問 “Google 相冊”。重繪了 Evince、數獨、掃雷和天氣應用的用户界面，同時增加了一款叫做 Hitori 的 GNOME 遊戲。</p><p><img src="https://github.com/paulcarroty/Articles/raw/master/GNOME_History/3.16/preview-apps.png" alt="GNOME 3.16"></p><p><em>GNOME 3.16, 2015</em></p><p>33000 處改變。主要的修改包括 UI 的配色方案從黑色變成了炭黑色。 增加了即現式滾動條。通知窗口中整合了日曆應用。對“文件”，圖像查看器和“地圖”等大量應用進行了微調。可以預覽應用程序。進一步從 X11 向 Wayland 移植。</p>',88)),e("p",null,[t[3]||(t[3]=p("感謝 GNOME Project 及 ",-1)),a(r,{href:"https://en.wikipedia.org/wiki/GNOME"},{default:o(()=>[...t[2]||(t[2]=[p("Wikipedia",-1)])]),_:1}),t[4]||(t[4]=p(" 提供的變更日誌！感謝閲讀！",-1))]),t[22]||(t[22]=e("hr",null,null,-1)),e("p",null,[t[6]||(t[6]=p("via: ",-1)),a(r,{href:"https://tlhp.cf/18-years-of-gnome-evolution/"},{default:o(()=>[...t[5]||(t[5]=[p("https://tlhp.cf/18-years-of-gnome-evolution/",-1)])]),_:1})]),e("p",null,[t[10]||(t[10]=p("作者：",-1)),a(r,{href:"https://tlhp.cf/author/paul/"},{default:o(()=>[...t[7]||(t[7]=[p("Pavlo Rudyi",-1)])]),_:1}),t[11]||(t[11]=p(" 譯者：",-1)),a(r,{href:"https://github.com/HaohongWANG"},{default:o(()=>[...t[8]||(t[8]=[p("Haohong WANG",-1)])]),_:1}),t[12]||(t[12]=p(" 校對：",-1)),a(r,{href:"https://github.com/wxy"},{default:o(()=>[...t[9]||(t[9]=[p("wxy",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=p("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[13]||(t[13]=[p("LCTT",-1)])]),_:1}),t[16]||(t[16]=p(" 原創編譯，",-1)),a(r,{href:"https://linux.cn/"},{default:o(()=>[...t[14]||(t[14]=[p("Linux中國",-1)])]),_:1}),t[17]||(t[17]=p(" 榮譽推出",-1))])])}const d=i(G,[["render",n]]);export{h as __pageData,d as default};
